<?php
declare(strict_types=1);require dirname(__DIR__).'/config/bootstrap.php';
use InaudisVote\Core\Authorization;use InaudisVote\Core\Csrf;use InaudisVote\Core\Navigation;use InaudisVote\Services\ElectionService;
$user=Authorization::requireRoles(['admin','organizer']);$id=(int)($_GET['id']??0);$election=ElectionService::find($id);
if(!$election||!Authorization::canManageElection($user,(int)$election['organization_id'],$id)){http_response_code(404);exit('Votación no encontrada.');}
$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!Csrf::validate($_POST['_csrf']??null))$error='Solicitud inválida.';
 else try{$action=(string)($_POST['action']??'');if($action==='add_question')ElectionService::addQuestion($id,$_POST);elseif($action==='delete_question')ElectionService::deleteQuestion($id,(int)($_POST['question_id']??0));else throw new RuntimeException('Acción no permitida en configuración.');header('Location: /election.php?id='.$id.'&ok=1');exit;}catch(Throwable $exception){$error=$exception->getMessage();}
}
$election=ElectionService::find($id);$questions=ElectionService::questions($id);$editable=in_array($election['status'],['draft','scheduled'],true)&&empty($election['ballot_locked_at']);$statusClass=$election['status']==='open'?'v-status-open':($election['status']==='closed'?'v-status-closed':'v-status-draft');
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=htmlspecialchars($election['title'])?> | QUORUM</title><link rel="stylesheet" href="/assets/quorum.css"></head><body class="vota-ui"><div class="v-shell">
<?php Navigation::sidebar($user, 'configuration', $id, $election['title']); ?>
<div class="v-main"><header class="v-topbar"><a class="v-link" href="/control.php?election_id=<?=$id?>">← Volver al centro de control</a><span style="flex:1"></span><a class="v-link" href="/logout.php">Salir</a></header><main class="v-content">
<div class="v-headrow"><div><div class="v-kicker"><?=htmlspecialchars($election['organization_name'])?></div><h1 class="v-title">Configuración de papeleta</h1><div class="v-accent-line"></div><p class="v-subtitle"><?=htmlspecialchars((string)$election['description'])?></p></div><span class="v-status <?=$statusClass?>"><?=htmlspecialchars($election['status'])?></span></div>
<?php if(isset($_GET['ok'])):?><div class="v-alert v-alert-ok">✓ Cambio guardado correctamente.</div><?php endif;?><?php if($error):?><div class="v-alert v-alert-error"><?=htmlspecialchars($error)?></div><?php endif;?><?php if(!$editable):?><div class="v-alert v-alert-warn"><strong>Papeleta bloqueada.</strong> La configuración queda en modo de solo lectura después de abrir.</div><?php endif;?>
<div class="v-grid-2" style="grid-template-columns:2fr 1fr"><section class="v-stack"><div class="v-card v-pad"><div class="v-section-head"><h2 style="margin:0">Papeleta</h2><span class="v-muted"><?=count($questions)?> pregunta(s)</span></div><?php if(!$questions):?><p class="v-muted">Agrega la primera pregunta para preparar el proceso.</p><?php endif;?><?php foreach($questions as $question):?><article style="border-top:1px solid var(--line);padding:18px 0"><div class="v-section-head"><div><strong><?=htmlspecialchars($question['text'])?></strong><div class="v-muted" style="font-size:12px;margin-top:4px"><?=htmlspecialchars($question['question_type'])?> · máximo <?=$question['max_choices']?></div></div><?php if($editable):?><form method="post" onsubmit="return confirm('¿Eliminar esta pregunta?');"><?=Csrf::input()?><input type="hidden" name="action" value="delete_question"><input type="hidden" name="question_id" value="<?=$question['id']?>"><button class="v-btn v-btn-danger">Eliminar</button></form><?php endif;?></div><?php foreach($question['options'] as $option):?><div class="v-option" style="cursor:default;padding:10px 13px"><span>○</span><?=htmlspecialchars($option['label'])?></div><?php endforeach;?></article><?php endforeach;?></div>
<?php if($editable):?><div class="v-card v-pad"><h2 style="margin-top:0">Agregar pregunta</h2><form method="post" class="v-stack"><?=Csrf::input()?><input type="hidden" name="action" value="add_question"><textarea class="v-field" name="text" required placeholder="Escribe la pregunta"></textarea><select class="v-field" name="question_type"><option value="single">Selección única</option><option value="multiple">Selección múltiple</option></select><input class="v-field" type="number" name="max_choices" min="1" value="1"><textarea class="v-field" name="options" required rows="5" placeholder="Una alternativa por línea"></textarea><button class="v-btn v-btn-orange">＋ Agregar pregunta</button></form></div><?php endif;?></section>
<aside class="v-stack"><div class="v-card v-pad"><h2 style="margin-top:0">Estado del proceso</h2><p class="v-muted">Los cambios de estado se realizan únicamente desde el Centro de Control, con confirmación y trazabilidad.</p><a class="v-btn v-btn-primary" href="/control.php?election_id=<?=$id?>">Ir al Centro de Control →</a></div><div class="v-card v-pad"><h2 style="margin-top:0">Resumen</h2><p><span class="v-muted">Modo</span><br><strong><?=htmlspecialchars($election['voting_mode'])?></strong></p><p><span class="v-muted">Ponderado</span><br><strong><?=$election['allow_weighted_vote']?'Sí':'No'?></strong></p><p><span class="v-muted">Inicio</span><br><?=htmlspecialchars((string)$election['starts_at'])?></p><p><span class="v-muted">Término</span><br><?=htmlspecialchars((string)$election['ends_at'])?></p></div></aside></div>
</main></div></div></body></html>
